            score += - (abs(ox - nx) + abs(oy - ny))

        # Deterministic tie-breaker
        if score > best_score:
            best_score = score
            best_move = (dx, dy)
        elif score == best_score:
            if (dx, dy) < best_move:
                best_move = (dx, dy)

    dx, dy = best_move
    return [int(dx), int(dy)]

